Title: ${x.title || ''}
Concept: ${x.concept || ''}
Visual direction: ${x.visual_direction || ''}
Music style: ${x.suno_style || ''}
Lyrics context: ${String(x.lyrics || '').slice(0, 4000)}
Source context: ${String(x.source_text || '').slice(0, 2000)}`;

