const raw = String(
  $json.output ||
  $json.text ||
  $json.response ||
  ''
).trim();

const ctx = $('Parse H3 Image Upload').first().json;

function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch (_) {}

  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);

  if (fenced) {
    try {
      return JSON.parse(fenced[1]);
    } catch (_) {}
  }

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');

  if (start >= 0 && end > start) {
    try {
      return JSON.parse(text.slice(start, end + 1));
    } catch (_) {}
  }

  return null;
}

const parsed = parseJson(raw);

if (!parsed || typeof parsed !== 'object') {
  throw new Error('H3 Video Director returned invalid JSON');
}

const description = String(
  parsed.integrated_multimodal_description || ''
).trim();

const soundscape = String(
  parsed.overall_soundscape || ''
).trim();

const music = String(
  parsed.non_diegetic_music || ''
).trim();

if (!description) {
  throw new Error(
    'Missing integrated_multimodal_description'
  );
}

if (!soundscape) {
  throw new Error(
    'Missing overall_soundscape'
  );
}

if (!music) {
  throw new Error(
    'Missing non_diegetic_music'
  );
}

// Build the exact prompt structure expected by MiniMax H3
const h3_prompt = [
  `integrated_multimodal_description: ${description}`,
  ``,
  `overall_soundscape: ${soundscape}`,
  ``,
  `non_diegetic_music: ${music}`
].join('\n');

return [{
  json: {
    ...ctx,
    h3_prompt,
    h3_director_output: {
