// ============================================================
// DSV - TELEGRAM NORMALIZER
// ============================================================
// Supports:
//   1. Normal Telegram messages
//   2. Telegram callback_query
//
// Callback formats:
//   regenerate:lyrics:<run_id>
//   regenerate:image:<run_id>
//   suno_data:<run_id>
//   generate_video:image:<run_id>
//   add_music:<run_id>
//   regenerate:youtube_meta:<run_id>
//   upload_youtube:<run_id>:<variant_id>
// ============================================================

const message = input.message || null;
const callback = input.callback_query || null;

// ------------------------------------------------------------
// CALLBACK QUERY
// ------------------------------------------------------------
if (callback) {
  const data = String(callback.data || '').trim();
  const from = callback.from || {};
  const callbackMessage = callback.message || {};
  const chat = callbackMessage.chat || {};

  let callback_action = null;
  let callback_target = null;
  let run_id = null;
  let variant_id = null;

  let match;

  // ----------------------------------------------------------
  // regenerate:lyrics:<run_id>
  // regenerate:image:<run_id>
  // ----------------------------------------------------------
  match = data.match(/^regenerate:(lyrics|image):(.+)$/);

  if (match) {
    callback_action = 'regenerate';
    callback_target = match[1];
    run_id = match[2];
  }

  // ----------------------------------------------------------
  // suno_data:<run_id>
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^suno_data:(.+)$/);

    if (match) {
      callback_action = 'suno_data';
      callback_target = 'lyrics';
      run_id = match[1];
    }
  }

  // ----------------------------------------------------------
  // generate_video:image:<run_id>
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^generate_video:image:(.+)$/);

    if (match) {
      callback_action = 'generate_video';
      callback_target = 'image';
      run_id = match[1];
    }
  }

  // ----------------------------------------------------------
  // add_music:<run_id>
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^add_music:(.+)$/);

    if (match) {
      callback_action = 'add_music';
      callback_target = 'audio';
      run_id = match[1];
    }
  }

  // ----------------------------------------------------------
  // regenerate:youtube_meta:<run_id>
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^regenerate:youtube_meta:(.+)$/);

    if (match) {
      callback_action = 'regenerate_youtube_meta';
      callback_target = 'youtube';
      run_id = match[1];
    }
  }

  // ----------------------------------------------------------
  // upload_youtube:<run_id>:<variant_id>
  // Example:
  // upload_youtube:run_123:final
  // upload_youtube:run_123:lyrics-en
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^upload_youtube:([^:]+):(.+)$/);

    if (match) {
      callback_action = 'upload_youtube';
      callback_target = match[2];
      run_id = match[1];
      variant_id = match[2];
    }
  }

  // ----------------------------------------------------------
  // Backward compatibility:
  // upload_youtube:<variant_id>
  //
  // This format does NOT contain run_id.
  // We keep parsing it, but run_id must be resolved elsewhere.
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^upload_youtube:(.+)$/);

    if (match) {
      callback_action = 'upload_youtube';
      callback_target = match[1];
      variant_id = match[1];

      // Do NOT invent run_id.
      run_id = null;
    }
  }

  // ----------------------------------------------------------
  // Old format:
  // upload:youtube:<run_id>
  //
  // Keep temporarily for backward compatibility.
  // ----------------------------------------------------------
  if (!callback_action) {
    match = data.match(/^upload:youtube:(.+)$/);

    if (match) {
      callback_action = 'upload_youtube';
      callback_target = 'final';
      run_id = match[1];
      variant_id = 'final';
    }
  }

  // ----------------------------------------------------------
  // Validate callback
  // ----------------------------------------------------------
  if (!callback.id) {
    throw new Error(
      'Normalize Telegram Input: callback_query.id is missing.'
    );
  }

  if (!data) {
    throw new Error(
      'Normalize Telegram Input: callback_query.data is missing.'
    );
  }

  if (!callback_action) {
    throw new Error(
      `Normalize Telegram Input: unsupported callback_data: ${data}`
    );
  }

  // ----------------------------------------------------------
  // For YouTube upload, run_id is mandatory.
  // ----------------------------------------------------------
  if (callback_action === 'upload_youtube' && !run_id) {
    throw new Error(
      `Normalize Telegram Input: YouTube upload callback does not contain run_id: ${data}`
    );
  }

  if (!callback_target) {
    throw new Error(
      `Normalize Telegram Input: callback_target is missing: ${data}`
    );
  }

  return [
    {
      json: {
        input_type: 'callback_query',
        is_callback: true,
        is_message: false,

        callback_query_id: String(callback.id),
        callback_id: String(callback.id),
        callback_data: data,

        callback_action,
        callback_target,

        // YouTube-specific
        variant_id:
          callback_action === 'upload_youtube'
            ? variant_id
            : null,

        // Canonical callback run identifier
        run_id,
        callback_run_id: run_id,

        chat_id: chat.id ?? null,
        callback_chat_id: chat.id ?? null,

        message_id:
          callbackMessage.message_id ??
          null,

        callback_message_id:
          callbackMessage.message_id ??
          null,

        user_id:
          from.id ??
          null,

        username:
          from.username ||
          null,

        first_name:
          from.first_name ||
          null,

        last_name:
          from.last_name ||
          null,

        text: '',

        raw_message: callbackMessage,
        raw_callback_query: callback,

        received_at: new Date().toISOString()
      }
    }
  ];
}

