const wrapText = (text, maxLength = 75) => {
  const words = String(text || '').split(/\s+/);
  const lines = [];
  let line = '';

  for (const word of words) {
    if (!line) {
      line = word;
      continue;
    }

    if ((line + ' ' + word).length <= maxLength) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }

  if (line) {
    lines.push(line);
  }

  return lines.join('\n');
};

