const INTRO_OFFSET = 5;

// Line cuối không có timestamp kế tiếp,
// nên cần một khoảng thời gian hiển thị tối thiểu.
const LAST_LINE_DURATION = 5;

// ============================================================
// LRC TIME -> ASS TIME
// ============================================================

function lrcTimeToSeconds(time) {
  const m = time.match(/^(\d+):(\d+(?:\.\d+)?)$/);

  if (!m) {
    return null;
  }

  const minutes = Number(m[1]);
  const seconds = Number(m[2]);

  if (
    !Number.isFinite(minutes) ||
    !Number.isFinite(seconds) ||
    seconds >= 60
  ) {
    return null;
  }

  return minutes * 60 + seconds + INTRO_OFFSET;
}

function secondsToAssTime(total) {
  if (!Number.isFinite(total) || total < 0) {
    return null;
  }

  const h = Math.floor(total / 3600);
  const min = Math.floor((total % 3600) / 60);
  const sec = Math.floor(total % 60);

  // ASS uses centiseconds.
  // Round instead of floor to reduce timestamp drift.
  const cs = Math.round((total % 1) * 100);

  // Handle rounding to exactly 100 centiseconds.
  if (cs >= 100) {
    const corrected = total + 0.01;

    const h2 = Math.floor(corrected / 3600);
    const min2 = Math.floor((corrected % 3600) / 60);
    const sec2 = Math.floor(corrected % 60);
    const cs2 = Math.floor(
      ((corrected % 1) + 1e-9) * 100
    );

    return `${h2}:${String(min2).padStart(2, '0')}:${String(sec2).padStart(2, '0')}.${String(cs2).padStart(2, '0')}`;
  }

  return `${h}:${String(min).padStart(2, '0')}:${String(sec).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

