const prepare = $('Prepare Burn Lyrics').first().json;

// ============================================================
// 1. Resolve run_id
// ============================================================

const run_id = String(
  prepare.run_id ||
  prepare.production_state?.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error(
    'Missing run_id while updating final video variants.'
  );
}

// ============================================================
// 2. Validate Burn Lyrics response
// ============================================================

if (String(burn.status || '').toLowerCase() !== 'ok') {
  throw new Error(
    `Burn Lyrics failed for ${run_id}: ${JSON.stringify(burn)}`
  );
}

// ============================================================
// 3. Resolve language
// ============================================================

const language = String(
  prepare.language ||
  prepare.video_language ||
  ''
).trim().toLowerCase();

if (!language) {
  throw new Error(
    `Missing lyrics language for ${run_id}`
  );
}

const variant_id = `lyrics-${language}`;

// ============================================================
// 4. Resolve output path
// ============================================================

const outputPath = String(
  burn.output ||
  burn.output_path ||
  prepare.burned_lyrics_output_path ||
  ''
).trim();

if (!outputPath) {
  throw new Error(
    `Missing burned video output path for ${run_id}`
  );
}

// ============================================================
// 5. Canonical production path
// ============================================================

const canonicalPath = outputPath
  .replace(/^\/data\//, '')
  .replace(/^data\//, '')
  .replace(/^\/+/, '');

const filename =
  canonicalPath.split('/').pop() ||
  `${run_id}-final-lyrics-${language}.mp4`;

// ============================================================
// 6. Resolve media metadata
// ============================================================

const durationRaw =
  burn.duration_seconds ??
  burn.duration ??
  prepare.final_video_duration ??
  prepare.duration_seconds ??
  null;

const duration =
  durationRaw !== null && durationRaw !== undefined
    ? Number(durationRaw)
    : null;

const fileSize =
  burn.file_size_bytes ??
  burn.size_bytes ??
  null;

const now = new Date().toISOString();

// ============================================================
// 7. Resolve production state
// ============================================================

const sourceState =
  prepare.production_state ||
  $('Prepare Burn Lyrics').first().json.production_state;

if (!sourceState || typeof sourceState !== 'object') {
  throw new Error(
    `Production state missing for run_id: ${run_id}`
  );
}

const state = JSON.parse(
  JSON.stringify(sourceState)
);

if (
  state.run_id &&
  String(state.run_id).trim() !== run_id
) {
  throw new Error(
    `run_id mismatch: expected ${run_id}, got ${state.run_id}`
  );
}

state.run_id = run_id;

// ============================================================
// 8. Initialize final_videos catalog
// ============================================================

state.final_videos = state.final_videos || {};

state.final_videos.default_variant =
  state.final_videos.default_variant || 'final';

state.final_videos.items = Array.isArray(
  state.final_videos.items
)
  ? state.final_videos.items
  : [];

// ============================================================
// 9. Build variant
// ============================================================

const variant = {
  variant_id,
  language,
  label: `${language.toUpperCase()} Lyrics`,
  path: canonicalPath,
  filename,
  mime_type: 'video/mp4',
  duration_seconds:
    Number.isFinite(duration) && duration > 0
      ? duration
      : null,
  file_size_bytes: fileSize,
  status: 'ready',
  created_at: now,
  updated_at: now
};

// ============================================================
// 10. Upsert variant by variant_id
// ============================================================

const index = state.final_videos.items.findIndex(
  item =>
    String(item?.variant_id || '') === variant_id
);

if (index >= 0) {
  const previous = state.final_videos.items[index];

  state.final_videos.items[index] = {
    ...previous,
    ...variant,
    created_at: previous.created_at || now
  };
} else {
  state.final_videos.items.push(variant);
}

// ============================================================
// 11. Sort default variant first
// ============================================================

state.final_videos.items.sort((a, b) => {
  if (
    a.variant_id ===
    state.final_videos.default_variant
  ) {
    return -1;
  }

  if (
    b.variant_id ===
    state.final_videos.default_variant
  ) {
    return 1;
  }

  return String(a.variant_id || '').localeCompare(
    String(b.variant_id || '')
  );
});

// ============================================================
// 12. Update status
// ============================================================

state.status = state.status || {};
state.status.final_videos = 'ready';
state.status.video_variants = 'ready';
state.updated_at = now;

// ============================================================
// 13. Return clean state
// ============================================================

return [
  {
    json: state  
  }
];

const source = $input.first().json.data;

if (!source || typeof source !== 'object') {
  throw new Error('Input data / production state missing.');
}

const run_id = String(
  source.run_id ||
  source.production_state?.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id.');
}

const chat_id = source.chat_id;

if (chat_id === null || chat_id === undefined || chat_id === '') {
  throw new Error(`Missing chat_id for run_id: ${run_id}`);
}

const state = source;

const finalVideos = state.final_videos;

if (!finalVideos || !Array.isArray(finalVideos.items)) {
  throw new Error(`final_videos.items missing for run_id: ${run_id}`);
}

const items = finalVideos.items
  .filter(item =>
    item &&
    String(item.variant_id || '').trim() &&
    String(item.path || '').trim()
  )
  .map(item => {
    const variant_id = String(item.variant_id).trim();

    const language = item.language
      ? String(item.language).trim()
      : null;

    const label = String(
      item.label ||
      (
        variant_id === 'final'
          ? 'Original'
          : language
            ? `${language.toUpperCase()} Lyrics`
            : variant_id
      )
    ).trim();

    const path = String(item.path).trim();

    const filename = String(
      item.filename ||
      path.split('/').pop() ||
      ''
    ).trim();

    return {
      variant_id,
      language,
      label,
      filename,
      path,
      status: String(item.status || 'ready').trim()
    };
  })
  .filter(item => item.status === 'ready');

if (!items.length) {
  throw new Error(
    `No ready final video variants found for run_id: ${run_id}`
  );
}

const defaultVariant = String(
  finalVideos.default_variant || 'final'
).trim();

items.sort((a, b) => {
  if (a.variant_id === defaultVariant) return -1;
  if (b.variant_id === defaultVariant) return 1;

  if (a.variant_id === 'final') return -1;
  if (b.variant_id === 'final') return 1;

  return a.variant_id.localeCompare(b.variant_id);
});

const rows = items.map(item => ({
  row: {
    buttons: [
      {
        text: `Upload ${item.label}`,
        additionalFields: {
          callback_data: `upload_youtube:${run_id}:${item.variant_id}`
        }
      }
    ]
  }
}));

return [{
  json: {
    run_id,
    chat_id,
    default_variant: defaultVariant,
    final_video_variants: items,
    telegram_inline_keyboard: {
      rows
    }
  }
}];

const raw = $json;

// ============================================================
// 1. Resolve production state
// ============================================================

const data = raw.data || raw;
const state = data.production_state || data;

if (!state || typeof state !== 'object') {
  throw new Error('Production state is missing or invalid.');
}

// ============================================================
// 2. Resolve callback
// ============================================================

let callback = null;

try {
  callback = $('Parse Callback').first().json;
} catch (_) {
  callback = null;
}

const run_id = String(
  state.run_id ||
  data.run_id ||
  callback?.run_id ||
  ''
).trim();

if (!run_id) {
  throw new Error('Missing run_id.');
}

const chat_id =
  state.chat_id ??
  data.chat_id ??
  callback?.chat_id ??
  null;

if (chat_id === null || chat_id === undefined || chat_id === '') {
  throw new Error(`Missing chat_id for run_id: ${run_id}`);
}

// ============================================================
// 3. Resolve callback action / variant
// ============================================================

const callbackData = String(
  callback?.callback_data ||
  callback?.data ||
  ''
).trim();

let callbackAction = String(
  callback?.callback_action ||
  ''
).trim();

let callbackTarget = String(
  callback?.callback_target ||
  callback?.variant_id ||
  ''
).trim();

// Parse upload_youtube:<variant_id>
if (callbackData) {
  const separator = callbackData.indexOf(':');

  if (separator >= 0) {
    const actionFromData = callbackData.slice(0, separator).trim();
    const targetFromData = callbackData.slice(separator + 1).trim();

    if (!callbackAction) {
      callbackAction = actionFromData;
    }

    if (!callbackTarget) {
      callbackTarget = targetFromData;
    }
  } else if (!callbackAction) {
    callbackAction = callbackData;
  }
}

if (callbackAction && callbackAction !== 'upload_youtube' && callbackAction !== 'upload') {
  throw new Error(
    `Invalid YouTube upload callback action: ${callbackAction}`
  );
}

// ============================================================
// 4. Resolve final video variants
// ============================================================

const finalVideos = state.final_videos;

if (!finalVideos || !Array.isArray(finalVideos.items)) {
  throw new Error(
    `final_videos.items missing for run_id: ${run_id}`
  );
}

const readyVariants = finalVideos.items
  .filter(item =>
    item &&
    String(item.variant_id || '').trim() &&
    String(item.path || '').trim() &&
    String(item.status || 'ready').trim() === 'ready'
  );

if (!readyVariants.length) {
  throw new Error(
    `No ready final video variants found for run_id: ${run_id}`
  );
}

const defaultVariant = String(
  finalVideos.default_variant || 'final'
).trim();

const variantId = callbackTarget || defaultVariant;

const selectedVariant = readyVariants.find(
  item => String(item.variant_id || '').trim() === variantId
);

if (!selectedVariant) {
  const available = readyVariants
    .map(item => String(item.variant_id || '').trim())
    .filter(Boolean)
    .join(', ');

  throw new Error(
    `Requested YouTube variant '${variantId}' is not ready or does not exist. Available variants: ${available}`
  );
}

// ============================================================
// 5. Resolve selected video
// ============================================================

const video_variant = String(
  selectedVariant.variant_id
).trim();

const video_language = selectedVariant.language
  ? String(selectedVariant.language).trim()
  : null;

const video_source_path = String(
  selectedVariant.path || ''
).trim();

if (!video_source_path) {
  throw new Error(
    `Selected variant '${video_variant}' has no file path.`
  );
}

function runtimePath(path) {
  const value = String(path || '').trim();

  if (!value) return '';
  if (value.startsWith('/data/')) return value;
  if (value.startsWith('data/')) return `/${value}`;

  return `/data/${value.replace(/^\/+/, '')}`;
}

const runtimeVideoPath = runtimePath(video_source_path);

const video_filename = String(
  selectedVariant.filename ||
  runtimeVideoPath.split('/').pop() ||
  ''
).trim();

if (!video_filename) {
  throw new Error(
    `Unable to resolve filename for variant '${video_variant}'.`
  );
}

// ============================================================
// 6. Resolve selected variant metadata
// ============================================================

const youtubeMeta = state.youtube_meta || {};

const youtubeMetaVersion = Number(
  youtubeMeta.version || 0
);

const youtubeTitle = String(
  youtubeMeta.title ||
  state.lyrics?.current?.title ||
  video_filename.replace(/\.[^.]+$/, '') ||
  run_id
).trim();

const youtubeDescription = String(
  youtubeMeta.description ||
  ''
).trim();

const youtubeTags = Array.isArray(youtubeMeta.tags)
  ? youtubeMeta.tags
  : [];

const youtubeHashtags = Array.isArray(youtubeMeta.hashtags)
  ? youtubeMeta.hashtags
  : [];

const youtubeCategoryId = String(
  youtubeMeta.category_id || '10'
).trim();

const youtubePrivacyStatus = String(
  youtubeMeta.privacy_status || 'private'
).trim();

// ============================================================
// 7. Selected video metadata
// ============================================================

const finalVideoDuration = Number(
  selectedVariant.duration_seconds ??
  state.final_video?.duration_seconds ??
  0
);

const finalVideoFileSize =
  selectedVariant.file_size_bytes ??
  null;

const finalVideoMimeType = String(
  selectedVariant.mime_type ||
  'video/mp4'
).trim();

// ============================================================
// 8. Return normalized upload context
// ============================================================

return [
  {
    json: {
      run_id,
      chat_id,

      message_id:
        state.message_id ??
        callback?.message_id ??
        null,

      user_id:
        state.user_id ??
        null,

      username:
        state.username ??
        null,

      callback_id:
        callback?.callback_id ??
        null,

      callback_data: callbackData || null,
      callback_action: callbackAction || 'upload_youtube',
      callback_target: callbackTarget || variantId,

      video_variant,
      video_language,
      video_source_path: runtimeVideoPath,
      video_filename,

      final_video_path: runtimeVideoPath,
      final_video_filename: video_filename,
      final_video_duration: finalVideoDuration,
      final_video_file_size: finalVideoFileSize,
      final_video_mime_type: finalVideoMimeType,

      youtube_meta_version: youtubeMetaVersion,
      youtube_title: youtubeTitle,
      youtube_description: youtubeDescription,
      youtube_tags: youtubeTags,
      youtube_hashtags: youtubeHashtags,
      youtube_category_id: youtubeCategoryId,
      youtube_privacy_status: youtubePrivacyStatus,

      youtube_meta: youtubeMeta,

      selected_video_variant: selectedVariant,
      final_video_variants: readyVariants,

      production_state: state
    }
  }
];

const input = $json;

const chat_id = input.chat_id;

if (chat_id === null || chat_id === undefined || chat_id === '') {
  throw new Error('Missing chat_id for UI notification.');
}

const label =
  input.video_variant === 'final'
    ? 'Original'
    : input.video_language
      ? `${String(input.video_language).toUpperCase()} Lyrics`
      : input.video_variant;

return [
  {
    json: {
      ...input,
      ui_chat_id: chat_id,
      ui_text: `☁️ Đang upload lên YouTube...\n\nVariant: ${label}\nFile: ${input.video_filename}`
    }
  }
];

const upload = $json;
const source = $('Prepare Upload YouTube').first().json;

const run_id = String(source.run_id || '').trim();

if (!run_id) {
  throw new Error('Missing run_id while saving YouTube upload.');
}

const chat_id = source.chat_id;

const state = source.production_state;

if (!state || typeof state !== 'object') {
  throw new Error(
    `Production state not found while saving YouTube upload: ${run_id}`
  );
}

// ============================================================
// 0. Resolve YouTube Video ID
// ============================================================
//
// n8n YouTube node currently returns:
//
// {
//   "uploadId": "IgZf69X-qRM"
// }
//
// In this workflow, uploadId is the actual YouTube video ID.
//

const videoId =
  upload.id ||
  upload.videoId ||
  upload.video_id ||
  upload.uploadId ||
  upload.data?.id ||
  upload.data?.uploadId ||
  null;

// ============================================================
// 1. Resolve YouTube URL
// ============================================================

const url =
  upload.url ||
  upload.data?.url ||
  (
    videoId
      ? `https://www.youtube.com/watch?v=${videoId}`
      : null
  );

if (!videoId) {
  throw new Error(
    `YouTube upload succeeded without a video ID: ${run_id}. ` +
    `Response=${JSON.stringify(upload)}`
  );
}

const uploadedAt = new Date().toISOString();

// ============================================================
// 2. Resolve Video Variant
// ============================================================

const variantId = String(
  source.video_variant ||
  source.callback_target ||
  'final'
).trim();

const variantLanguage = source.video_language
  ? String(source.video_language).trim()
  : null;

// ============================================================
// 3. Per-variant upload history
// ============================================================

state.youtube_uploads =
  state.youtube_uploads &&
  typeof state.youtube_uploads === 'object'
    ? state.youtube_uploads
    : {};

state.youtube_uploads[variantId] = {
  status: 'uploaded',

  video_id: videoId,
  url,

  uploaded_at: uploadedAt,

  variant_id: variantId,
  variant_language: variantLanguage,

  filename: source.video_filename || null,
  file_path: source.video_source_path || null,

  metadata_version: Number(
    state.youtube_meta?.version ||
    source.youtube_meta_version ||
    0
  )
};

// ============================================================
// 4. Backward-compatible canonical youtube_upload
// ============================================================

state.youtube_upload = {
  ...state.youtube_upload,
  ...state.youtube_uploads[variantId]
};

// ============================================================
// 5. Update production state status
// ============================================================

state.status = state.status || {};

state.status.youtube_upload = 'ready';
state.status.youtube_uploads = 'ready';

state.updated_at = uploadedAt;

// ============================================================
// 6. Return
// ============================================================

return [
  {
    json: {
      ...source,

      run_id,
      chat_id,

      youtube_video_id: videoId,
      youtube_url: url,
      youtube_uploaded_at: uploadedAt,

      video_variant: variantId,
      video_language: variantLanguage,
      video_filename: source.video_filename || null,
      video_source_path: source.video_source_path || null,

      production_state: state,

      youtube_upload: state.youtube_upload,
      youtube_upload_variant: state.youtube_uploads[variantId],
      youtube_uploads: state.youtube_uploads,

      state_saved: false
    }
  }
];
